  // Βρες νομό από συντεταγμένες (fallback αν το geocoding δεν δίνει νομό)
  static String? findPrefectureByCoords(double lat, double lon) {
    String? best;
    double bestArea = double.infinity;
    for (final entry in prefBounds.entries) {
      final b = entry.value;
      if (lat >= b[0] && lat <= b[1] && lon >= b[2] && lon <= b[3]) {
        final area = (b[1] - b[0]) * (b[3] - b[2]);
        if (area < bestArea) {
          bestArea = area;
          best = entry.key;
        }
      }
    }
    return best;
  }

  // Βρες ελληνικό όνομα νομού από αγγλικό (geocoding result)
  static String? resolvePrefecture(String? enName) {
    if (enName == null) return null;
    if (enToGr.containsKey(enName)) return enToGr[enName];
    for (final entry in enToGr.entries) {
      if (enName.contains(entry.key)) return entry.value;
    }
    if (adjacency.containsKey(enName)) return enName;
    return null;
  }

  // Επιστρέφει παραλίες προσβάσιμες οδικά από τον νομό, ταξινομημένες κατά απόσταση
  static List<Map<String, dynamic>> beachesNear(
      String prefecture, double lat, double lon) {
    final accessible = adjacency[prefecture] ?? [prefecture];
    final result = beaches
        .where((b) => accessible.contains(b['pref']))
        .map((b) {
      final dlat = (b['lat'] as double) - lat;
      final dlon = (b['lon'] as double) - lon;
      final distKm = 111.0 * (dlat * dlat + dlon * dlon) / 2;
      return {
        'name': b['name'],
        'lat': b['lat'],
        'lon': b['lon'],
        'pref': b['pref'],
        'distKm': double.parse(distKm.toStringAsFixed(1)),
      };
    }).toList();
    result.sort((a, b) =>
        (a['distKm'] as double).compareTo(b['distKm'] as double));
    return result;
  }
